package com.agacostays.billing.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.util.StringUtils;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter{private final String secret,issuer;public JwtAuthenticationFilter(@Value("${security.jwt.secret}")String s,@Value("${security.jwt.issuer}")String i){secret=s;issuer=i;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(StringUtils.hasText(h)&&h.startsWith("Bearer ")){try{var key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));Claims cl=Jwts.parser().verifyWith(key).requireIssuer(issuer).build().parseSignedClaims(h.substring(7)).getPayload();String role=cl.get("role",String.class);String sub=cl.getSubject();if(role!=null&&sub!=null){var a=new UsernamePasswordAuthenticationToken(sub,null,List.of(new SimpleGrantedAuthority("ROLE_"+role.replace("ROLE_",""))));SecurityContextHolder.getContext().setAuthentication(a);}}catch(Exception ignored){}}c.doFilter(r,p);}}
